<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, ref } from 'vue'
import { api, post } from '../api'
import {permissionName,scopeText,capabilityMeta,capabilityName,groupedCapabilities,categoryNames} from '@domain-pack/uiText'
import {authorizationUi} from '@domain-pack/uiPolicy'
import OrganizationPanel from './OrganizationPanel.vue'
const emit=defineEmits<{error:[message:string]}>()
const users=ref<any[]>([]),grants=ref<any[]>([]),catalog=ref<any>({permissions:{}}),selected=ref<any>(null),scopeResources=ref<any[]>([]),groups=ref<any[]>([])
const assignedCapabilities=ref<any[]>([]),capabilityReason=ref('')
const capabilitySearch=ref(''),capabilityDepartment=ref(''),capabilityType=ref('')
const selectedDepartment=ref('全部')
const deleteTarget=ref<any>(null)
const grantSelection=ref<string[]>([]),grantCategories=ref<string[]>(['raw_material']),grantAll=ref(false),grantCrossDepartment=ref(false)
const grantSearch=ref(''),grantDepartmentFilter=ref(''),grantBaseDepartment=ref('')
const grantTypeFilter=ref('')
const grantTypes=[{key:'read',name:'查询'},{key:'create',name:'新建'},{key:'submit',name:'发起审批'},{key:'approve',name:'审批'},{key:'execute',name:'执行'},{key:'manage',name:'管理'},{key:'confirm',name:'确认'},{key:'issue',name:'下单/发出'}]
const grantGroups=[
 {key:'purchase',name:'采购部',hint:'采购申请、采购价格、采购订单及供应商付款',prefixes:['purchase.','purchase_price.','order.','supplier_payment.']},
 {key:'design',name:'设计部',hint:'设计路线、项目资料和物料基础资料',prefixes:['design_route.','master.manage','project.']},
 {key:'production',name:'生产部',hint:'装配、计划、试模和工程变更',prefixes:['assembly.','project_plan.','plan_change.','trial_request.','change.']},
 {key:'warehouse',name:'仓储/品质部',hint:'仓储、收货、检验和库存',prefixes:['warehouse.','receipt.','inspection.','stock.']},
 {key:'contact',name:'工程联络部',hint:'工程联络单及协作处理',prefixes:['contact.']},
 {key:'system',name:'管理部门',hint:'用户、流程、审计和邮件管理',prefixes:['workflow.','user.manage','grant.manage','audit.read','mail.','file.upload']},
]
const capabilityDepartments=computed(()=>Array.from(new Map(assignedCapabilities.value.map((item:any)=>{const meta=capabilityMeta(item);return [meta.department,meta.departmentName]})).entries()))
const capabilityTypes=computed(()=>Array.from(new Map(assignedCapabilities.value.map((item:any)=>{const meta=capabilityMeta(item);return [meta.type,meta.typeName]})).entries()))
function capabilityMatches(item:any){
 const meta=capabilityMeta(item),keyword=capabilitySearch.value.trim().toLowerCase()
 if(capabilityDepartment.value&&meta.department!==capabilityDepartment.value)return false
 if(capabilityType.value&&meta.type!==capabilityType.value)return false
 if(!keyword)return true
 return [item.key,capabilityName(item),item.description,item.permission,meta.departmentName,meta.typeName].some(value=>String(value||'').toLowerCase().includes(keyword))
}
const filteredAssignedCapabilities=computed(()=>assignedCapabilities.value.filter(capabilityMatches))
const assignedCapabilityGroups=computed(()=>groupedCapabilities(filteredAssignedCapabilities.value))
const activeUserCount=computed(()=>users.value.filter((u:any)=>u.active!==false).length)
const superAdminCount=computed(()=>users.value.filter((u:any)=>u.super_admin).length)
const departmentNames=computed(()=>Array.from(new Set(users.value.map((u:any)=>String(u.department||'未设置部门').trim()).filter(Boolean))).sort((a,b)=>a.localeCompare(b,'zh-CN')))
const departmentCounts=computed(()=>new Map(departmentNames.value.map((name:string)=>[name,users.value.filter((u:any)=>String(u.department||'未设置部门').trim()===name).length])))
const visibleUsers=computed(()=>selectedDepartment.value==='全部'?users.value:users.value.filter((u:any)=>String(u.department||'未设置部门').trim()===selectedDepartment.value))
const departmentOptions=computed(()=>{
 const result:any[]=[]
 const seen=new Set<string>()
 for(const g of groups.value.filter((g:any)=>g.kind==='DEPARTMENT'&&g.active)){if(!seen.has(g.name)){seen.add(g.name);result.push(g)}}
 for(const name of departmentNames.value){if(!seen.has(name)){result.push({id:`department:${name}`,name,kind:'DEPARTMENT',active:true,members:[],version:1})}}
 return result
})
const roleOptions=computed(()=>groups.value.filter((g:any)=>g.kind==='ROLE'&&g.active))
const adding=ref(false),editing=ref<any>(null),busy=ref(false),username=ref(''),name=ref(''),department=ref(''),role=ref(''),password=ref(''),editName=ref(''),editDepartment=ref(''),editRole=ref(''),permission=ref(authorizationUi.defaultPermission),scopeResource=ref(''),category=ref(authorizationUi.defaultCategory),all=ref(false),reason=ref(''),effect=ref('ALLOW')
const permissionUnrestricted=computed(()=>authorizationUi.unrestrictedPermissions.includes(permission.value))
const permissionHint=computed(()=>authorizationUi.permissionHints[permission.value]||'')
const categoryScoped=computed(()=>authorizationUi.categoryPermissionPrefixes.some((prefix:string)=>permission.value.startsWith(prefix)))
const createDropdown=ref<'department'|'role'|''>('')
const departmentLabel=computed(()=>department.value||'选择部门')
const roleLabel=computed(()=>roleOptions.value.find((g:any)=>g.id===role.value)?.name||'暂不分配角色')
function toggleCreateDropdown(kind:'department'|'role'){createDropdown.value=createDropdown.value===kind?'':kind}
function pickDepartment(value:string){department.value=value;createDropdown.value=''}
function pickRole(value:string){role.value=value;createDropdown.value=''}
function resetCreate(){username.value='';name.value='';department.value='';role.value='';password.value='';createDropdown.value=''}
function closeCreate(){adding.value=false;editing.value=null;resetCreate()}
async function startEdit(target:any){editing.value=target;selected.value=target;editName.value=target.display_name||'';editDepartment.value=target.department||'';editRole.value=groups.value.find((g:any)=>g.kind==='ROLE'&&g.members?.some((m:any)=>m.user_id===target.id))?.id||'';grantCrossDepartment.value=false;grantAll.value=false;grantCategories.value=target.department==='采购部'?['raw_material']:['raw_material'];const deptGroup=target.department==='设计部'?'design':target.department==='生产部'?'production':target.department==='仓储部'||target.department==='品质部'?'warehouse':target.department==='管理部门'?'system':target.department==='采购部'?'purchase':'';grantBaseDepartment.value=deptGroup;grantDepartmentFilter.value=deptGroup;grantSelection.value=deptGroup?grantGroupKeys(grantGroups.find((group:any)=>group.key===deptGroup)):[];try{[grants.value,assignedCapabilities.value]=await Promise.all([api(`/users/${target.id}/grants`),api(`/users/${target.id}/capabilities`)]);if(target.super_admin)grants.value=[]}catch(e:any){emit('error',e.message)}}
function closeEdit(){editing.value=null;editName.value='';editDepartment.value='';editRole.value=''}
function userRoles(user:any){return groups.value.filter((g:any)=>g.kind==='ROLE'&&g.members?.some((m:any)=>m.user_id===user.id)).map((g:any)=>g.name)}
async function load(){const [userData,catalogData,groupData]=await Promise.all([api('/users'),api('/catalog'),api('/organization/groups')]);users.value=userData.filter((u:any)=>u.active!==false);catalog.value=catalogData;groups.value=groupData;scopeResources.value=authorizationUi.resourceEndpoint?await api(authorizationUi.resourceEndpoint):[]}
async function choose(user:any){try{selected.value=user;[grants.value,assignedCapabilities.value]=await Promise.all([api(`/users/${user.id}/grants`),api(`/users/${user.id}/capabilities`)]);requestAnimationFrame(()=>document.querySelector('.admin-permission-page > section:last-child')?.scrollIntoView({behavior:'smooth',block:'start'}))}catch(e:any){emit('error',e.message)}}
async function toggleCapability(item:any){busy.value=true;try{const id=selected.value.id;await post(`/users/${id}/capabilities`,{kind:item.kind,key:item.key,enabled:!item.enabled,reason:capabilityReason.value,expected_security_version:selected.value.security_version});await load();await choose(users.value.find(u=>u.id===id))}catch(e:any){emit('error',e.message)}finally{busy.value=false}}
function handleModalBackdrop(event:MouseEvent){const target=event.target as HTMLElement|null;if(!target||!target.classList.contains('modal-shade'))return;if(editing.value)closeEdit();else if(adding.value)closeCreate();else if(deleteTarget.value)cancelRemoveUser()}
function handleModalKeydown(event:KeyboardEvent){if(event.key!=='Escape'||busy.value)return;if(editing.value)closeEdit();else if(adding.value)closeCreate();else if(deleteTarget.value)cancelRemoveUser()}
onMounted(async()=>{document.addEventListener('click',handleModalBackdrop);document.addEventListener('keydown',handleModalKeydown);try{await load()}catch(e:any){emit('error',e.message)}})
onBeforeUnmount(()=>{document.removeEventListener('click',handleModalBackdrop);document.removeEventListener('keydown',handleModalKeydown)})
async function create(){if(editing.value){await saveEdit();adding.value=false;return}busy.value=true;try{const created=await post('/users',{username:username.value,display_name:name.value,department:department.value,password:password.value});const pickedRole=groups.value.find((g:any)=>g.id===role.value);if(pickedRole){await api(`/organization/groups/${pickedRole.id}`,{method:'PUT',body:JSON.stringify({kind:pickedRole.kind,name:pickedRole.name,members:[...(pickedRole.members||[]),{user_id:created.id,is_head:false}],active:pickedRole.active,reason:'创建用户时分配角色',expected_version:pickedRole.version})})}closeCreate();await load();const fresh=users.value.find((u:any)=>u.id===created.id);if(fresh)await choose(fresh)}catch(e:any){emit('error',e.message)}finally{busy.value=false}}
async function removeUser(target:any){
 if(target.super_admin)return
 deleteTarget.value=target
}
async function confirmRemoveUser(){
 const target=deleteTarget.value
 if(!target)return
 deleteTarget.value=null
 busy.value=true
 try{await api(`/users/${target.id}`,{method:'DELETE'});if(selected.value?.id===target.id){selected.value=null;grants.value=[];assignedCapabilities.value=[]}await load()}
 catch(e:any){emit('error',e.message)}finally{busy.value=false}
}
function cancelRemoveUser(){if(!busy.value)deleteTarget.value=null}
function grantGroupKeys(group:any){return Object.keys(catalog.value.permissions||{}).filter(key=>group.prefixes.some((prefix:string)=>key===prefix||key.startsWith(prefix)))}
const filteredGrantKeys=computed(()=>{const keyword=grantSearch.value.trim().toLowerCase();return Object.keys(catalog.value.permissions||{}).filter(key=>{const group=grantGroups.find((item:any)=>item.key===grantDepartmentFilter.value);const departmentOk=!group||grantGroupKeys(group).includes(key);const typeOk=!grantTypeFilter.value||key.endsWith(`.${grantTypeFilter.value}`);return departmentOk&&typeOk&&(!keyword||permissionName(key).toLowerCase().includes(keyword)||key.toLowerCase().includes(keyword))})})
function toggleGrantGroup(group:any){if(group.key!==grantBaseDepartment.value&&!grantCrossDepartment.value)return;grantDepartmentFilter.value=group.key;const keys=grantGroupKeys(group);const allSelected=keys.length>0&&keys.every(key=>grantSelection.value.includes(key));grantSelection.value=allSelected?grantSelection.value.filter(key=>!keys.includes(key)):Array.from(new Set([...grantSelection.value,...keys]))}
function toggleGrantKey(key:string){grantSelection.value=grantSelection.value.includes(key)?grantSelection.value.filter(item=>item!==key):[...grantSelection.value,key]}
async function bulkGrant(){if(!selected.value||!grantSelection.value.length)return;busy.value=true;try{let version=selected.value.security_version;for(const key of grantSelection.value){const categoryScoped=key.startsWith('purchase.')||key.startsWith('contact.');const scope=grantAll.value||!categoryScoped?{all:true}:{category:(grantCrossDepartment.value?grantCategories.value:['raw_material']).length?(grantCrossDepartment.value?grantCategories.value:['raw_material']):['raw_material']};const result=await post(`/users/${selected.value.id}/grants`,{permission:key,effect:'ALLOW',scope,fields:catalog.value.permissions[key],reason:reason.value.trim()||'编辑人员时批量授权',expected_security_version:version});version=result.security_version}grantSelection.value=[];reason.value='';selected.value.security_version=version;await load();const fresh=users.value.find((u:any)=>u.id===selected.value.id);if(fresh){selected.value=fresh;grants.value=await api(`/users/${fresh.id}/grants`)}}catch(e:any){emit('error',e.message)}finally{busy.value=false}}
async function saveEdit(){if(!editing.value)return;busy.value=true;try{const id=editing.value.id;await api(`/users/${id}`,{method:'PUT',body:JSON.stringify({display_name:editName.value,department:editDepartment.value})});const previous=groups.value.find((g:any)=>g.kind==='ROLE'&&g.members?.some((m:any)=>m.user_id===id));if(previous?.id!==editRole.value){for(const group of [previous,groups.value.find((g:any)=>g.id===editRole.value)].filter(Boolean)){const members=(group.members||[]).filter((m:any)=>m.user_id!==id);if(group.id===editRole.value)members.push({user_id:id,is_head:false});await api(`/organization/groups/${group.id}`,{method:'PUT',body:JSON.stringify({kind:group.kind,name:group.name,members,active:group.active,reason:'编辑人员时调整角色',expected_version:group.version})})}}closeEdit();await load();const fresh=users.value.find((u:any)=>u.id===id);if(fresh)selected.value=fresh}catch(e:any){emit('error',e.message)}finally{busy.value=false}}
async function grant(){busy.value=true;try{const scope:any=(all.value||permissionUnrestricted.value)?{all:true}:{[authorizationUi.resourceScopeKey]:[scopeResource.value]};if(!all.value&&categoryScoped.value&&authorizationUi.categoryScopeKey)scope[authorizationUi.categoryScopeKey]=[category.value];await post(`/users/${selected.value.id}/grants`,{permission:permission.value,effect:effect.value,scope,fields:catalog.value.permissions[permission.value],reason:reason.value,expected_security_version:selected.value.security_version});const id=selected.value.id;await load();await choose(users.value.find(u=>u.id===id))}catch(e:any){emit('error',e.message)}finally{busy.value=false}}
async function revoke(g:any){busy.value=true;try{await api(`/users/${selected.value.id}/grants/${g.id}?expected_security_version=${selected.value.security_version}`,{method:'DELETE'});const id=selected.value.id;await load();await choose(users.value.find(u=>u.id===id))}catch(e:any){emit('error',e.message)}finally{busy.value=false}}
</script>
<template><div class="admin-permission-page"><div class="admin-page-head"><div><h2>人员与权限</h2><p class="muted">按人员维护账号、部门、角色和授权范围；角色只作为审批候选规则，不自动扩大权限。</p></div><div class="admin-head-actions"><span class="admin-stat"><strong>{{activeUserCount}}</strong> 用户</span><span class="admin-stat"><strong>{{superAdminCount}}</strong> 管理员</span><button class="primary" @click="adding=true">创建用户</button></div></div>
<section class="surface admin-user-card admin-user-workbench"><aside class="admin-department-tree"><div class="admin-department-head"><h3>部门</h3><span>{{departmentNames.length}} 个</span></div><button class="admin-department-item" :class="{active:selectedDepartment==='全部'}" @click="selectedDepartment='全部'"><span>全部人员</span><strong>{{users.length}}</strong></button><button v-for="name in departmentNames" :key="name" class="admin-department-item" :class="{active:selectedDepartment===name}" @click="selectedDepartment=name"><span>{{name}}</span><strong>{{departmentCounts.get(name)}}</strong></button></aside><div class="admin-user-grid-panel"><div class="admin-card-title"><div><h3>人员列表</h3><p class="muted">按部门查看人员；点击姓名可维护授权范围。</p></div><span class="admin-result-count">{{visibleUsers.length}} 人</span></div><div class="admin-user-grid-scroll"><table class="admin-user-grid"><thead><tr><th>用户名称</th><th>部门</th><th>角色</th><th>状态</th><th>创建时间</th><th>操作</th></tr></thead><tbody><tr v-for="u in visibleUsers" :key="u.id" :class="{active:selected?.id===u.id}"><td><button class="admin-user-link" @click="choose(u)"><span class="avatar"><img v-if="u.avatar_url" :src="u.avatar_url" alt=""/><template v-else>{{(u.display_name||u.username||'?')[0]}}</template></span><span><strong>{{u.display_name}}</strong></span></button></td><td>{{u.department||'未设置部门'}}</td><td>{{userRoles(u).join('、')||'未分配角色'}}</td><td><span v-if="u.super_admin" class="admin-user-badge">超级管理员</span><span v-else class="admin-user-status">正常</span></td><td>{{u.created_at?new Date(u.created_at).toLocaleString('zh-CN',{hour12:false}):'—'}}</td><td><div class="admin-user-actions"><button type="button" class="link-button" @click.stop="choose(u)">授权</button><button type="button" class="link-button" @click.stop="startEdit(u)">编辑</button><button type="button" v-if="!u.super_admin" class="danger-ghost" :disabled="busy" @click.stop="removeUser(u)">删除</button></div></td></tr><tr v-if="!visibleUsers.length"><td colspan="6" class="admin-empty-cell">该部门暂无人员</td></tr></tbody></table></div></div></section>
<details class="surface admin-user-card admin-organization-details"><summary><span><strong>组织与业务角色</strong><small>维护部门、通用角色和业务对象范围内的流程选人职责</small></span></summary><OrganizationPanel @changed="load" @error="emit('error',$event)"/></details>
<Teleport to="body"><div v-if="adding" class="modal-shade"><form class="modal form-stack admin-create-modal" role="dialog" aria-modal="true" aria-label="创建用户" @submit.prevent="create"><div class="admin-modal-head"><div><h2>创建用户</h2><p class="muted">填写基础人员信息，创建后自动进入人员列表。</p></div><button type="button" class="icon-button" aria-label="关闭" @click="closeCreate">×</button></div><div class="admin-create-grid"><label>登录账号<input v-model="username" required pattern="[a-zA-Z0-9_.-]{3,80}" placeholder="例如 zhangsan"/></label><label>姓名<input v-model="name" required placeholder="请输入姓名"/></label><label>部门<div class="admin-create-select" :class="{open:createDropdown==='department'}"><button type="button" class="admin-create-select-button" :disabled="!departmentOptions.length" @click="toggleCreateDropdown('department')"><span :class="{placeholder:!department}">{{departmentOptions.length?departmentLabel:'请先配置部门'}}</span><i aria-hidden="true"></i></button><div v-if="createDropdown==='department'" class="admin-create-select-menu"><button v-for="g in departmentOptions" :key="g.id" type="button" :class="{active:department===g.name}" @click="pickDepartment(g.name)">{{g.name}}</button></div></div></label><label>角色<div class="admin-create-select" :class="{open:createDropdown==='role'}"><button type="button" class="admin-create-select-button" @click="toggleCreateDropdown('role')"><span :class="{placeholder:!role}">{{roleLabel}}</span><i aria-hidden="true"></i></button><div v-if="createDropdown==='role'" class="admin-create-select-menu"><button type="button" :class="{active:!role}" @click="pickRole('')">暂不分配角色</button><button v-for="g in roleOptions" :key="g.id" type="button" :class="{active:role===g.id}" @click="pickRole(g.id)">{{g.name}}</button></div></div></label><label class="admin-create-wide">初始密码<input v-model="password" type="password" minlength="12" autocomplete="new-password" required placeholder="至少 12 位"/></label></div><p v-if="!departmentOptions.length" class="admin-create-hint muted">当前没有可用部门，先在流程或后台配置部门后再创建人员。</p><div class="actions"><button type="button" :disabled="busy" @click="closeCreate">取消</button><button class="primary" :disabled="busy||!departmentOptions.length||!department">{{busy?'正在创建…':'确定创建'}}</button></div></form></div></Teleport>
<section v-if="selected" class="surface form-stack"><h3>{{selected.display_name}}的授权</h3><p v-if="selected.super_admin" class="muted">超级管理员具有全量已实现能力，但仍受业务规则、当前席位与人工确认约束。</p>
<div v-for="g in grants.filter(x=>x.active)" :key="g.id" class="grant-row"><div><strong>{{permissionName(g.permission)}} · {{g.effect==='ALLOW'?'允许':'拒绝'}}</strong><small>{{scopeText(g.scope,scopeResources)}}</small></div><button :disabled="busy" @click="revoke(g)">撤销</button></div>
<form v-if="!selected.super_admin" @submit.prevent="grant" class="form-stack"><h3>增加一项完整授权</h3><label>业务动作<select v-model="permission"><option v-for="(_,key) in catalog.permissions" :key="key" :value="key">{{permissionName(String(key))}}</option></select></label><label>效果<select v-model="effect"><option value="ALLOW">允许</option><option value="DENY">明确拒绝</option></select></label><p v-if="permissionHint" class="muted">{{permissionHint}}</p><label v-if="!permissionUnrestricted" class="check-label"><input v-model="all" type="checkbox"/>{{authorizationUi.allScopeLabel}}</label><template v-if="!all&&!permissionUnrestricted&&authorizationUi.resourceEndpoint"><label>{{authorizationUi.resourceLabel}}<select v-model="scopeResource" required><option value="" disabled>{{authorizationUi.resourcePlaceholder}}</option><option v-for="resource in scopeResources" :key="resource.id" :value="resource.id">{{resource[authorizationUi.resourceCodeField]}}</option></select></label><label v-if="categoryScoped">{{authorizationUi.categoryLabel}}<select v-model="category"><option v-for="(label,key) in authorizationUi.categoryOptions" :key="key" :value="key">{{label}}</option></select></label></template><label>授权原因<input v-model="reason" required/></label><p class="muted">{{authorizationUi.scopeHelp}}</p><button class="primary" :disabled="busy">确认保存授权</button></form><section v-if="!selected.super_admin" class="form-stack"><h3>工具与技能</h3><p class="muted">能力分配与业务权限取交集。启用工具不会扩大数据范围；停用后，进行中的任务会停止继续使用该能力。</p><label>能力变更原因<input v-model="capabilityReason" placeholder="填写启用或停用原因"/></label><div class="capability-filter"><label>查找能力<input v-model="capabilitySearch" placeholder="输入工具、权限或说明关键词"/></label><label>部门<select v-model="capabilityDepartment"><option value="">全部部门</option><option v-for="[key,name] in capabilityDepartments" :key="key" :value="key">{{name}}</option></select></label><label>类型<select v-model="capabilityType"><option value="">全部类型</option><option v-for="[key,name] in capabilityTypes" :key="key" :value="key">{{name}}</option></select></label></div><div class="capability-groups compact capability-grid"><section v-for="department in assignedCapabilityGroups" :key="department.key" class="capability-department"><h3>{{department.name}}</h3><div v-for="type in department.types" :key="type.key" class="capability-type-block"><div class="capability-type-heading"><strong>{{type.name}}</strong><small class="muted">{{type.items.length}} 项</small></div><div v-for="item in type.items" :key="item.kind+item.key" class="grant-row capability-assignment"><div><strong>{{capabilityName(item)}} · {{item.kind==='TOOL'?'工具':'技能'}}</strong><div class="capability-tags"><span>{{capabilityMeta(item).departmentName}}</span><span>{{capabilityMeta(item).typeName}}</span></div><small>{{item.description}}</small><small>{{item.enabled?(item.effective?'已启用 · 当前可用':'已启用 · 缺少业务权限或依赖工具'):'未启用'}}</small></div><button :disabled="busy||!capabilityReason.trim()" @click="toggleCapability(item)">{{item.enabled?'停用':'启用'}}</button></div></div></section></div><p v-if="!filteredAssignedCapabilities.length" class="muted">没有匹配的工具或技能。</p></section></section></div>
<Teleport to="body"><div v-if="editing" class="modal-shade"><form class="modal form-stack admin-create-modal admin-edit-modal" role="dialog" aria-modal="true" aria-label="编辑用户" @submit.prevent="saveEdit"><div class="admin-modal-head"><div><h2>编辑用户</h2><p class="muted">修改姓名、部门、角色和授权，账号本身保持不变。</p></div><button type="button" class="icon-button" aria-label="关闭" @click="closeEdit">×</button></div><div class="admin-create-grid"><label>用户名称<input v-model="editName" required/></label><label>部门<input v-model="editDepartment" placeholder="例如 设计部"/></label><label>角色<select v-model="editRole"><option value="">暂不分配角色</option><option v-for="g in roleOptions" :key="g.id" :value="g.id">{{g.name}}</option></select></label></div><section class="admin-edit-permissions"><div class="admin-edit-section-head"><h3>已有授权</h3><span>{{grants.filter(g=>g.active).length}} 项</span></div><div v-if="!grants.filter(g=>g.active).length" class="muted">暂未配置授权</div><div v-for="g in grants.filter(g=>g.active)" :key="g.id" class="admin-edit-grant"><span>{{permissionName(g.permission)}} · {{g.effect==='ALLOW'?'允许':'拒绝'}}</span><small>{{scopeText(g.scope,scopeResources)}}</small></div><div v-if="!editing.super_admin" class="admin-bulk-grant"><h3>批量新增授权</h3><p class="muted">当前人员部门：{{editing.department||'未设置部门'}}。默认按本部门授权，勾选跨部门后再选择其他责任域。</p><div class="admin-grant-layout"><div class="admin-grant-groups"><label v-for="group in grantGroups" :key="group.key" class="admin-grant-group"><input type="checkbox" :checked="grantGroupKeys(group).length>0&&grantGroupKeys(group).every(key=>grantSelection.includes(key))" @change="toggleGrantGroup(group)"/><span><strong>{{group.name}}</strong><small>{{group.hint}}</small></span></label></div><div class="admin-grant-detail"><div class="admin-grant-filter-row"><label class="admin-grant-search">搜索权限<input v-model="grantSearch" placeholder="输入采购申请、原材、审批等关键词"/></label><label class="admin-grant-type-select">类型<select v-model="grantTypeFilter"><option value="">全部类型</option><option v-for="type in grantTypes" :key="type.key" :value="type.key">{{type.name}}</option></select></label></div><div class="admin-grant-permissions"><label v-for="key in filteredGrantKeys" :key="key" class="admin-grant-permission"><input type="checkbox" :checked="grantSelection.includes(key)" @change="toggleGrantKey(key)"/><span>{{permissionName(key)}}</span></label></div></div></div><div class="admin-grant-scope"><label class="check-label"><input v-model="grantCrossDepartment" type="checkbox"/>跨部门授权（切换其他部门）</label><label v-if="grantCrossDepartment&&grantDepartmentFilter==='purchase'" class="check-label"><input v-model="grantAll" type="checkbox"/>全部采购责任域</label><template v-if="grantCrossDepartment&&grantDepartmentFilter==='purchase'"><label v-for="(label,key) in categoryNames" :key="key" class="check-label"><input v-model="grantCategories" :value="key" type="checkbox"/>{{label}}</label></template><span v-else class="muted">当前部门默认范围</span></div><div class="admin-edit-grant-form"><label>授权原因<input v-model="reason" placeholder="填写授权原因"/></label><button type="button" class="primary" :disabled="busy||!grantSelection.length||!reason.trim()" @click="bulkGrant">批量添加 {{grantSelection.length}} 项</button></div></div></section><div class="actions"><button type="button" :disabled="busy" @click="closeEdit">取消</button><button class="primary" :disabled="busy||!editName.trim()">{{busy?'正在保存…':'保存修改'}}</button></div></form></div></Teleport>
<Teleport to="body"><div v-if="deleteTarget" class="modal-shade admin-confirm-shade" @click.self="cancelRemoveUser"><section class="modal admin-confirm-modal" role="dialog" aria-modal="true" aria-labelledby="delete-user-title"><div class="admin-confirm-icon">!</div><div class="admin-confirm-copy"><h2 id="delete-user-title">停用人员账号</h2><p>确定停用“{{deleteTarget.display_name||deleteTarget.username}}”吗？停用后将无法登录，但历史记录会保留。</p></div><div class="admin-confirm-actions"><button type="button" :disabled="busy" @click="cancelRemoveUser">取消</button><button type="button" class="danger-solid" :disabled="busy" @click="confirmRemoveUser">{{busy?'处理中…':'确认停用'}}</button></div></section></div></Teleport>
</template>
